from flask import Flask, request

app = Flask(__name__)
TAREFAS = []
PERMITIDOS = {"titulo", "feita"}

def erros_de(dado):
    if not isinstance(dado, dict):
        return ["corpo inválido: esperava um objeto JSON"]

    erros = []
    titulo = dado.get("titulo")
    if not isinstance(titulo, str) or not 3 <= len(titulo.strip()) <= 120:
        erros.append("titulo: texto de 3 a 120 caracteres")
    if not isinstance(dado.get("feita", False), bool):
        erros.append("feita: verdadeiro ou falso")
    return erros

@app.post("/tarefas")
def criar():
    dado = request.get_json(silent=True)
    erros = erros_de(dado)
    if erros:
        return {"erros": erros}, 400

    limpo = {c: v for c, v in dado.items() if c in PERMITIDOS}   # ignora o resto
    tarefa = {"id": len(TAREFAS) + 1, "titulo": limpo["titulo"].strip(), "feita": limpo.get("feita", False)}
    TAREFAS.append(tarefa)
    return tarefa, 201

# os quatro testes:
# válido        201 com a tarefa
# titulo curto  400 {"erros": ["titulo: texto de 3 a 120 caracteres"]}
# sem titulo    400, a mesma mensagem
# JSON quebrado 400 {"erros": ["corpo inválido: esperava um objeto JSON"]}
#
# o silent=True é o que transforma JSON quebrado em None em vez de exceção,
# e por isso o quarto caso cai na mesma checagem dos outros.

