const express = require("express");

const app = express();
app.use(express.json());

const TAREFAS = [];

function errosDe(corpo) {
  const erros = [];
  const titulo = corpo?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 3 || titulo.trim().length > 120) {
    erros.push("titulo: texto de 3 a 120 caracteres");
  }
  if (corpo?.feita !== undefined && typeof corpo.feita !== "boolean") {
    erros.push("feita: verdadeiro ou falso");
  }
  return erros;
}

app.post("/tarefas", (req, res) => {
  const erros = errosDe(req.body);
  if (erros.length) return res.status(400).json({ erros });

  const tarefa = { id: TAREFAS.length + 1, titulo: req.body.titulo.trim(), feita: req.body.feita ?? false };
  TAREFAS.push(tarefa);                       // só os campos que eu escolhi
  res.status(201).location(`/tarefas/${tarefa.id}`).json(tarefa);
});

// JSON quebrado explode no express.json(): este tratador transforma em 400
app.use((erro, req, res, proximo) => {
  if (erro instanceof SyntaxError) return res.status(400).json({ erros: ["corpo inválido: JSON malformado"] });
  proximo(erro);
});

app.listen(3000);

// os quatro testes:
// válido        201 com a tarefa e o cabeçalho Location
// titulo curto  400 {"erros":["titulo: texto de 3 a 120 caracteres"]}
// sem titulo    400, a mesma mensagem
