import logging
from fastapi import FastAPI, HTTPException, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse

app = FastAPI()
log = logging.getLogger("api")

# formato da casa: {"erro": "..."} e, na validação, {"erro": "...", "campos": [...]}

@app.exception_handler(HTTPException)
async def conhecido(req: Request, exc: HTTPException):
    return JSONResponse(status_code=exc.status_code, content={"erro": exc.detail})

@app.exception_handler(RequestValidationError)
async def invalido(req: Request, exc: RequestValidationError):
    campos = [{"campo": ".".join(str(p) for p in e["loc"][1:]), "problema": e["msg"]} for e in exc.errors()]
    return JSONResponse(status_code=400, content={"erro": "dados inválidos", "campos": campos})

@app.exception_handler(Exception)
async def inesperado(req: Request, exc: Exception):
    log.exception("falha em %s %s", req.method, req.url.path)
    return JSONResponse(status_code=500, content={"erro": "erro interno"})

@app.get("/quebra")
def quebra():
    return 1 / 0        # de propósito, pra ver o tratador trabalhando

# GET /quebra  ->  500 {"erro": "erro interno"}
