from flask import Blueprint, request
from . import servico

rotas = Blueprint("tarefas", __name__, url_prefix="/tarefas")

@rotas.post("")
def criar():
    dado = request.get_json(silent=True) or {}
    titulo = dado.get("titulo", "")
    if not isinstance(titulo, str) or len(titulo.strip()) < 3:
        return {"erro": "dados inválidos", "campos": ["titulo"]}, 400
    try:
        return servico.criar(titulo, bool(dado.get("feita", False))), 201
    except servico.TituloRepetido as erro:
        return {"erro": str(erro)}, 409

