// tarefas/servico.js
const repositorio = require("./repositorio");

class TituloRepetido extends Error {}

function criar(titulo, feita = false) {
  const limpo = titulo.trim();
  if (repositorio.listar().some((t) => t.titulo.toLowerCase() === limpo.toLowerCase())) {
    throw new TituloRepetido("já existe uma tarefa com esse título");
  }
  return repositorio.salvar({ titulo: limpo, feita });
}

module.exports = { criar, TituloRepetido };


// tarefas/rotas.js
const { Router } = require("express");
const servico = require("./servico");

const rotas = Router();

rotas.post("/", (req, res) => {
  const titulo = req.body?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 3) {
    return res.status(400).json({ erro: "dados inválidos", campos: ["titulo"] });
  }
  try {
    res.status(201).json(servico.criar(titulo, req.body.feita ?? false));
  } catch (erro) {
    if (erro instanceof servico.TituloRepetido) return res.status(409).json({ erro: erro.message });
    throw erro;                     // o resto sobe pro tratador central
  }
});

module.exports = rotas;
